    public void ApplyHistorySelection(string[] paths,string[] chosenSubjects,bool append){collections.Text=string.Join("\r\n",(append?Lines(collections.Text).Concat(paths):paths).Distinct());subjects.Text=string.Join("；",(append?SubjectLines(subjects.Text).Concat(chosenSubjects):chosenSubjects).Distinct());string[] topics=DualClassification.TopicsFromPaths(paths);if(topics.Length>0)research.Text=string.Join("；",append?SubjectLines(research.Text).Concat(topics).Distinct():topics);result.classificationMode="history";result.materialSource="history";string mode=DualClassification.ModeFor(Lines(collections.Text));generationMode.SelectedIndex=mode=="formula"?1:mode=="topic"?2:mode=="both"?0:3;tags.Text=string.Join("\r\n",MaterialThemes.TagsFor(Lines(tags.Text).Concat(SubjectLines(research.Text).Select(t=>"主题:"+t)),SubjectLines(subjects.Text),Lines(collections.Text)));error.Text="";UpdateClassificationStatus();}
    void UpdateClassificationStatus(){string[] paths=Lines(collections.Text);int formula=paths.Count(p=>DualClassification.Kind(p)=="化学通式"&&p!=FormulaCatalog.Pending),topic=paths.Count(p=>DualClassification.Kind(p)=="研究主题");classificationStatus.Text=(generationMode.SelectedIndex==3?"当前 "+paths.Length+" 条路径 · 可直接编辑":"化学通式 "+formula+" 条  ·  研究主题 "+topic+" 条")+"\r\nAI "+result.confidence.ToString("P0")+(result.materialSource=="title"?" · 题名线索，请核对化学式":" · 确认后才入库");}
    static string[] SubjectLines(string text){return text.Split(new[]{'；',';','\r','\n'},StringSplitOptions.RemoveEmptyEntries).Select(s=>s.Trim()).Where(s=>s.Length>0).ToArray();}
    static string[] Lines(string x){return x.Split(new[]{'\r','\n'},StringSplitOptions.RemoveEmptyEntries).Select(s=>s.Trim()).Where(s=>s.Length>0).ToArray();}
    static Panel Block(string text,Control control,bool multiline){Panel block=new Panel{Dock=DockStyle.Fill,BackColor=Design.Paper,Margin=Padding.Empty,Padding=new Padding(0,0,0,7)};Label label=Design.Label(text,9,Design.Muted);label.Dock=DockStyle.Top;label.Height=25;block.Controls.Add(Design.Field(control,multiline));block.Controls.Add(label);return block;}
